functions.body:
block([a,b,c,ca,cb,cc],
  a: p, b: qq, c: qq-p,
  if is(cross(a,b)=matrix([0],[0],[0])) then return(false),
  ca: dot(a,b), cb: dot(-a,c), cc: dot(-b,-c),
  if typ=1 then return(is(ca>0) and is(cb>0) and is(cc>0) and is(ca^2/(dot(a,a)*dot(b,b)) < cb^2/(dot(a,a)*dot(c,c))) and is(ca^2/(dot(a,a)*dot(b,b)) < cc^2/(dot(b,b)*dot(c,c)))),
  if typ=2 then return(is(ca=0)),
  return(is(ca<0)))
